import type { ColorFamily, GarmentTradition } from "../types";

/**
 * Real, buyable garment listings gathered from independent retailers on
 * 2026-08-15, used to answer the question the verdict raises:
 * "fine — where do I actually get one?"
 *
 * Provenance and its limits, because the distinction matters:
 *
 * - The colours in the user's palette are *measured* from their face.
 * - These garments are **not** measured. Retailer product photography is shot
 *   under styled lighting against varied backdrops, and running our garment
 *   extractor over it returns badly wrong answers — four emerald dresses came
 *   back as navy, teal, navy and black. So each listing is filed under the
 *   colour family named in the retailer's own product title, and the UI must
 *   say that is what it is. Claiming a measurement here would be a lie.
 *
 * Images are copied locally (see `public/shop/`) rather than hot-linked, so a
 * retailer blocking cross-origin requests cannot blank the section.
 *
 * Regenerate with the shopping-index flow rather than editing by hand; the
 * `url` values point at live product pages and will rot over time.
 */
export interface ShopListingRecord {
  id: string;
  title: string;
  retailer: string;
  url: string;
  /** Path under the frontend's public dir, prefixed with its base URL by the client. */
  imageUrl: string;
  colorFamily: ColorFamily;
  tradition: GarmentTradition;
}

